package edu.ucsd.sysnet.cluetoothscanner.ui.v3.data

import android.content.Context

/**
 * Bluetooth SIG assigned numbers, for reading an advertisement: company identifiers, 16-bit service and
 * member UUIDs, appearance values and AD type names. The data is `assets/sig-numbers.tsv`, generated by
 * `tools/sig-numbers.py` from a pinned snapshot of the SIG's public repository.
 *
 * [current] is empty until [load] runs (and in JVM tests); lookups then return null and callers show
 * the bare number.
 */
class SigNumbers(
    private val companies: Map<Int, String>,
    private val uuids16: Map<Int, String>,
    private val appearances: Map<Int, String>,
    private val adTypes: Map<Int, String>,
) {
    fun company(id: Int): String? = companies[id]

    fun uuid16(uuid: Int): String? = uuids16[uuid]

    fun appearance(value: Int): String? = appearances[value] ?: appearances[value and 0xFFC0]

    fun adType(type: Int): String? = adTypes[type]

    companion object {
        const val ASSET = "sig-numbers.tsv"

        val Empty = SigNumbers(emptyMap(), emptyMap(), emptyMap(), emptyMap())

        @Volatile
        var current: SigNumbers = Empty
            private set

        /** `kind<TAB>hex value<TAB>name` lines; `#` lines and anything malformed are skipped. */
        fun parse(lines: Sequence<String>): SigNumbers {
            val maps = mapOf(
                "company" to HashMap<Int, String>(),
                "uuid16" to HashMap(),
                "appearance" to HashMap(),
                "adtype" to HashMap(),
            )
            for (line in lines) {
                if (line.startsWith("#")) continue
                val parts = line.split('\t')
                if (parts.size != 3) continue
                val value = parts[1].toIntOrNull(16) ?: continue
                maps[parts[0]]?.put(value, parts[2])
            }
            return SigNumbers(maps.getValue("company"), maps.getValue("uuid16"), maps.getValue("appearance"), maps.getValue("adtype"))
        }

        /** Reads the asset once; call off the main thread. A missing or broken asset leaves [current] empty. */
        fun load(context: Context) {
            if (current !== Empty) return
            current = runCatching { context.assets.open(ASSET).bufferedReader().useLines { parse(it) } }.getOrDefault(Empty)
        }
    }
}
